<style>.role-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:20px}.role-list a{display:block;padding:12px;text-decoration:none;color:#526071;border-radius:9px;font-weight:600}.role-list a.active,.role-list a:hover{background:#eaf0ff;color:#246bfd}.permission-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:20px}.permission{display:flex;gap:12px;align-items:center;border:1px solid #e4eaf1;border-radius:10px;padding:14px;cursor:pointer}.permission:hover{border-color:#8eafff;background:#f8faff}.permission input{width:17px;height:17px;accent-color:#246bfd}.permission small{display:block;margin-top:3px;color:#8090a0}@media(max-width:700px){.role-layout,.permission-list{grid-template-columns:1fr}}</style>
<div class="role-layout"><section class="panel role-list"><h2>Role</h2><p class="muted">Pilih role yang akan diatur.</p><hr><?php foreach($roles as $role): ?><a class="<?= $selected_role==$role->id?'active':'' ?>" href="<?= site_url('admin/rolemenus/index/'.$role->id) ?>"><?= html_escape($role->nama_role) ?></a><?php endforeach; ?></section><form class="panel" method="post" action="<?= site_url('admin/rolemenus/save/'.$selected_role) ?>"><div class="panel-head"><div><h2>Hak akses menu</h2><p>Pilih menu yang ditampilkan untuk role ini.</p></div></div><div class="permission-list"><?php foreach($menus as $menu): ?><label class="permission"><input type="checkbox" name="menus[]" value="<?= $menu->id ?>" <?= in_array($menu->id,$checked)?'checked':'' ?>><span><b><?= html_escape($menu->icon) ?> <?= html_escape($menu->nama_menu) ?></b><small><?= html_escape($menu->url) ?></small></span></label><?php endforeach; ?></div><div class="form-actions"><button class="button primary">Simpan pengaturan</button></div></form></div>
